ll-watch.linux:
#!/bin/sh
# ll-watch: learning-loop shim. The plugin rewrites it when this text changes.
exec node -e "const fs=require('node:fs'),path=require('node:path'),home=require('node:os').homedir();const key='learning-loop@learning-loop-marketplace';function newest(base){try{const v=fs.readdirSync(base).filter((d)=>/^\d+\.\d+\.\d+$/.test(d)).sort((a,b)=>a.localeCompare(b,'en',{numeric:true})).pop();return v?path.join(base,v):null}catch{return null}}let installed;try{const j=JSON.parse(fs.readFileSync(path.join(home,'.claude','plugins','installed_plugins.json'),'utf8'));installed=(j.plugins||j)[key][0].installPath}catch{}const candidates=[installed,newest(path.join(home,'.claude','plugins','cache','learning-loop-marketplace','learning-loop')),newest(path.join(home,'.codex','plugins','cache','learning-loop-marketplace','learning-loop'))];const root=candidates.find((r)=>r&&fs.existsSync(path.join(r,'scripts','shim.mjs')));if(!root){console.error('learning-loop is not installed. Run: claude plugin install '+key);process.exit(1)}const shim=path.join(root,'scripts','shim.mjs');process.argv.splice(1,0,shim);import(require('node:url').pathToFileURL(shim).href);" -- ll-watch "$@"

